// The house template example set (spec section 2.6): five or six
// example designs created for this purpose, generic Tap.Giving
// artwork in the builder's own styles, NO customer artwork at all.
// Each design is a full-bleed 106 mm artboard SVG (the production
// canvas), rendered to PNG at build time by the asset pipeline in the
// private working notes; both files are committed under
// src/example-assets/ and imported as generated TypeScript string
// strings (the PNG modules, generated by tools/build-examples) so the
// Worker serves them with no extra binding.
//
// Each example carries: id, direction label in plain words, shape,
// displayUrl (served by this Worker at /examples/<id>.png).

import exNavyRoundSvg from "./example-assets/ex-navy-round.svg.ts";
import exNavyRoundPng from "./example-assets/ex-navy-round.png.ts";
import exCreamSquareSvg from "./example-assets/ex-cream-square.svg.ts";
import exCreamSquarePng from "./example-assets/ex-cream-square.png.ts";
import exForestRoundSvg from "./example-assets/ex-forest-round.svg.ts";
import exForestRoundPng from "./example-assets/ex-forest-round.png.ts";
import exBurgundySquareSvg from "./example-assets/ex-burgundy-square.svg.ts";
import exBurgundySquarePng from "./example-assets/ex-burgundy-square.png.ts";
import exSlateRoundSvg from "./example-assets/ex-slate-round.svg.ts";
import exSlateRoundPng from "./example-assets/ex-slate-round.png.ts";
import exSandSquareSvg from "./example-assets/ex-sand-square.svg.ts";
import exSandSquarePng from "./example-assets/ex-sand-square.png.ts";

export interface ExampleDesign {
  id: string;
  direction: string;
  pickLabel: string;
  shape: "round" | "square";
  svgText: string;
  pngBase64: string;
}

export const EXAMPLES: ExampleDesign[] = [
  { id: "ex-navy-round", direction: "Classic navy with a gold tap icon and a clean organization name", pickLabel: "Navy Blue & Gold", shape: "round", svgText: exNavyRoundSvg, pngBase64: exNavyRoundPng },
  { id: "ex-cream-square", direction: "Warm cream with serif lettering and a centered tap icon", pickLabel: "Warm Cream & Serif", shape: "square", svgText: exCreamSquareSvg, pngBase64: exCreamSquarePng },
  { id: "ex-forest-round", direction: "Deep green with an arched name and a small leaf accent", pickLabel: "Deep Green & Gold Leaf", shape: "round", svgText: exForestRoundSvg, pngBase64: exForestRoundPng },
  { id: "ex-burgundy-square", direction: "Burgundy with a thin gold border frame and bold lettering", pickLabel: "Burgundy & Gold Frame", shape: "square", svgText: exBurgundySquareSvg, pngBase64: exBurgundySquarePng },
  { id: "ex-slate-round", direction: "Modern slate with minimal type and a large tap icon", pickLabel: "Slate, Minimal White", shape: "round", svgText: exSlateRoundSvg, pngBase64: exSlateRoundPng },
  { id: "ex-sand-square", direction: "Soft sand with a stacked name and tagline treatment", pickLabel: "Soft Sand, Stacked Serif", shape: "square", svgText: exSandSquareSvg, pngBase64: exSandSquarePng },
];

export function exampleById(id: string): ExampleDesign | undefined {
  return EXAMPLES.find((e) => e.id === id);
}
